template:
fn read_and_modify(val: &mut i32) -> i32 {
    let ptr: *mut i32 = ⟦slot1⟧;
    unsafe {
        *ptr += 10;
    }
    ⟦slot2⟧
}

fn main() {
    let mut x = 5;
    println!("{}", read_and_modify(&mut x));
}

tests:
#[test]
fn modifies_via_pointer() {
    let mut x = 5;
    assert_eq!(read_and_modify(&mut x), 15);
    assert_eq!(x, 15);
}
